#!/usr/bin/env python3
"""论文二补充材料 S1–S5(Markdown,由结果文件生成)→ docs/paper2_supplement.md"""
import json, os, sys, platform
from pathlib import Path
import numpy as np
ROOT = Path(__file__).resolve().parents[1]; R = ROOT / "results"; J = lambda *p: json.load(open(R.joinpath(*p)))
L = []
def h(t): L.append(f"\n## {t}\n")
def tbl(header, rows):
    L.append("| " + " | ".join(header) + " |"); L.append("|" + "---|" * len(header))
    for r in rows: L.append("| " + " | ".join(str(x) for x in r) + " |")
    L.append("")
f3 = lambda x: f"{x:.3f}"
import sklearn, scipy
L.append("# Supplementary material — Benchmarking motor-imagery period detection in stroke EEG across four public datasets: fixed rules, trained classifiers, calibration budgets and a specificity audit\n")
L.append(f"Generated by `code/make_supplement_paper2.py`. Software: Python {platform.python_version()}, NumPy {np.__version__}, SciPy {scipy.__version__}, scikit-learn {sklearn.__version__}. Random seed 0 for fold assignment and bootstrap.\n")

# ---------------- S1
h("S1 Fold correction and fold-wise AUC")
L.append("S1.1 Before/after correction of cross-validation folds (acute, cue reference; chronic within-session). 'Before' used window-level stratification (`StratifiedKFold` on trial index mod 5), which placed the trial of 98/120 test windows in the training set; 'after' assigns whole trials to folds.\n")
rows = []
for w, lab in [("cue", "Acute cue"), ("break", "Acute break 0.25–1.75"), ("late", "Acute break 0.5–2.0")]:
    o = json.load(open(R / "_leaky_v0_backup" / f"summary_{w}.json"))["summary"]; n = J("stroke_mi_vs_rest", f"summary_{w}.json")["summary"]
    for k, kl in [("rule_oos_auc_8-30", "rule (out-of-sample ref.)"), ("rule_auc_8-30", "rule (same-source ref.)"), ("lda_auc_8-30", "LDA 2-feature"), ("csp_lda_auc_8-30", "CSP+LDA")]:
        rows.append([lab, kl, f3(o[k]["mean"]), f3(n[k]["mean"]), f"{n[k]['mean']-o[k]['mean']:+.3f}"])
o = json.load(open(R / "_leaky_v0_backup" / "summary.json"))["summary"]; n = J("stroke_chronic_mi_vs_rest", "summary.json")["summary"]
for k, kl in [("rule_auc", "rule (same-source ref.)"), ("lda_auc", "LDA 2-feature"), ("csp_lda_auc", "CSP+LDA")]:
    rows.append(["Chronic within-session", kl, f3(o[k]["mean"]), f3(n[k]["mean"]), f"{n[k]['mean']-o[k]['mean']:+.3f}"])
tbl(["Dataset/window", "Method", "Before", "After", "Δ"], rows)
S = J("paper2_followups", "supp_checks.json")["foldwise"]["summary"]
