tbl(["Method", "Concatenated", "Fold-wise mean"], [[m, f3(S[f"{m}_concat"]), f3(S[f"{m}_foldmean"])] for m in ["rule", "lda", "csp"]])
A = J("paper2_followups", "supp_checks.json")["amplitude"]; big = sorted(A, key=lambda d: -d["raw_ptp_median_uV"])[:3]
cue = {r["sub"]: r for r in J("stroke_mi_vs_rest", "summary_cue.json")["rows"]}
L.append("S1.3 Amplitude check. Median per-trial peak-to-peak amplitude of unfiltered C3/C4 (µV). Three patients exceed 1,000 µV (median of the others 119 µV).\n")
tbl(["Patient", "raw p-p median (µV)", "rule AUC", "LDA AUC", "CSP AUC"], [[d["sub"], f"{d['raw_ptp_median_uV']:.0f}", f3(cue[d["sub"]]["rule_oos_auc_8-30"]), f3(cue[d["sub"]]["lda_auc_8-30"]), f3(cue[d["sub"]]["csp_lda_auc_8-30"])] for d in big])
ex = {d["sub"] for d in big}
L.append("Main-window means after excluding these three: " + ", ".join(f"{kl} {np.mean([cue[s][k] for s in cue if s not in ex]):.3f}" for k, kl in [("rule_oos_auc_8-30", "rule"), ("lda_auc_8-30", "LDA"), ("csp_lda_auc_8-30", "CSP")]) + ".\n")

# S1.4 折内均值 vs 拼接 AUC(四个数据集,2026-10-07 格式审查后补;正文 3.1 与方法引用)
L.append("S1.4 Fold-wise mean versus pooled (concatenated) AUC in the main setting of each dataset (patient means; acute and chronic from the acute/chronic analyses and the strengthening runs, Tianjin first assessment after duplicate exclusion). Fold-wise means were not computed for two-feature LDA and CSP+LDA in the chronic within-session analysis.\n")
