_d = lambda rr, a: float(np.mean([r[a + "rule_c34"] - r[a + "lda_c34"] for r in rr])) if a == "" else float(np.mean([r["rule_c34_foldmean"] - r["lda_c34_foldmean"] for r in rr]))
