tbl(["Patient", "later sessions", "fixed (Youden)", "k=5", "k=10", "k=20", "offline", "fixed (ref-pct)", "k=10 (ref-pct)", "k=10 sens", "k=10 spec", "LDA fixed BA", "rule fixed AUC", "LDA fixed AUC"], rows)
