rows = [[s, PA[s]["side"], f3(MV[s]["rule2"]), f3(MV[s]["rule_lap"]), f3(MV[s]["rule_m7"]), f3(MT[s]["lda_7ch"]), f3(MT[s]["csp_7ch"]), f3(MT[s]["lda_29ch_power"]), f3(FR[s]["lda_29_rel"]), f3(MV[s]["csp_lda"]),
         f3(PA[s]["paretic_rule_oos"]), f3(PA[s]["paretic_rule_contra"]), f3(PA[s]["paretic_rule_ipsi"]), f3(FR[s]["rule_far"]), f3(FR[s]["rule_c34_minus_far"]), f3(FR[s]["lda_far"]), f3(FR[s]["lda_far_c34"]), f3(FR[s]["lda_rel_c34"]), f3(C2[s]["eog_rule_1-8"]), f3(C2[s]["c34_filt_only"]), f3(C2[s]["eog_reg_c34"])] for s in sorted(MV)]
