    L.append("S6.2 Paretic-hand MI vs rest, pre-training: early+late rest windows (1.0–2.5 + 4.0–5.5 s; sensitivity) versus late rest windows (4.0–5.5 + 5.5–7.0 s; main).\n")
    tbl(["Metric", "Early+late rest windows (sensitivity)", "Late rest windows (main)"], [[k, f3(np.mean([A_[s]['pre']['AH'][k] for s in subs])), f3(np.mean([B_[s]['pre']['AH'][k] for s in subs]))] for k in ["rule_c34", "lda_c34", "csp_all", "rule_far", "rule_c34_minus_far", "lda_far", "lda_far_c34", "eog_rule_1-8", "eog_rule_8-30", "rule_contra", "rule_ipsi"]])
